import{_ as e,H as t,f as o,i as p}from"./chunks/framework.DPC7el8K.js";const h=JSON.parse('{"title":"📊 中继台参数信息","description":"","frontmatter":{},"headers":[],"relativePath":"guide/09-中继台参数.md","filePath":"guide/09-中继台参数.md","lastUpdated":1780385104000}'),r={name:"guide/09-中继台参数.md"};function l(i,a,d,n,_,c){return t(),o("div",null,[...a[0]||(a[0]=[p('<h1 id="📊-中继台参数信息" tabindex="-1">📊 中继台参数信息 <a class="header-anchor" href="#📊-中继台参数信息" aria-label="Permalink to &quot;📊 中继台参数信息&quot;">​</a></h1><h3 id="具体参数" tabindex="-1">具体参数 <a class="header-anchor" href="#具体参数" aria-label="Permalink to &quot;具体参数&quot;">​</a></h3><blockquote><p>中继台呼号：BR4IL</p><p>中继台调制方式：模拟</p><p>中继台频率：439.550MHz，下差5MHz，亚音88.5</p></blockquote><h3 id="终端电台参数" tabindex="-1">终端电台参数 <a class="header-anchor" href="#终端电台参数" aria-label="Permalink to &quot;终端电台参数&quot;">​</a></h3><blockquote><p>接收频率439.550MHz</p><p>发射频率434.550MHz</p><p>亚音88.5</p></blockquote><h3 id="简要通联要求" tabindex="-1">简要通联要求 <a class="header-anchor" href="#简要通联要求" aria-label="Permalink to &quot;简要通联要求&quot;">​</a></h3><blockquote><p>1、严格遵守《中华人民共和国无线电管理条例》、《业余无线电台管理办法》及相关法规，不得讲与业余无线电无关的内容，包括但不限于政治，军事等敏感话题；</p><p>2、坚持业余无线电爱好者体谅、忠诚、进取、友爱、适度、爱国之准则；秉承相互尊重、和谐友爱的精神，相互学习、相互理解的心态快乐地与业余无线电一起成长；</p><p>3、在通联过程中，应当尊重其他友台的通信权利，不得进行干扰、侮辱和污蔑等不当行为，确保通信的文明与和谐。不得播放广告、音乐、广播节目、不得辱骂其他友台，不得喝酒以后上台通联，不得掐台，不得未经允许插入等；</p><p>4、如遇干扰等问题，请及时反馈，管理小组已建立友台反馈机制，及时收集大家的意见和建议，改进中继台设备和服务质量；</p><p>5、请大家爱护来之不易中继频率，互相监督，管理好自己的情绪，共同营造文明和谐的通联环境；</p><p>6、未取得呼号的友台请守听学习，尽早考取业余无线电操作证书、办理执照，在此之前不允许通联；</p><p>7、未尽事宜，请严格遵循《业余无线电台管理办法》及相关法规之政策；</p></blockquote><p>期待与各位空中相见！</p>',8)])])}const u=e(r,[["render",l]]);export{h as __pageData,u as default};
